<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('security.view');$risk=strtoupper((string)input('risk'));$q=trim((string)input('q'));$page=page_int();[$limit,$offset]=pagination($page);$where=[];$params=[];if(in_array($risk,['LOW','MEDIUM','HIGH','CRITICAL'],true)){$where[]='s.risk_level=?';$params[]=$risk;}if($q!==''){$where[]='(s.event_type LIKE ? OR s.description LIKE ? OR u.name LIKE ? OR s.ip_address LIKE ?)';$params=array_fill(0,4,'%'.$q.'%');}$sqlWhere=$where?' WHERE '.implode(' AND ',$where):'';$count=db()->prepare('SELECT COUNT(*) FROM security_events s LEFT JOIN users u ON u.id=s.user_id'.$sqlWhere);$count->execute($params);$total=(int)$count->fetchColumn();$stmt=db()->prepare('SELECT s.*,u.name FROM security_events s LEFT JOIN users u ON u.id=s.user_id'.$sqlWhere.' ORDER BY s.id DESC LIMIT '.$limit.' OFFSET '.$offset);$stmt->execute($params);$rows=$stmt->fetchAll();$pageTitle='Security events';$pageSubtitle='Device, login and transaction risk signals';require APP_ROOT.'/includes/header.php';?>
<section class="panel"><form class="filters"><input name="q" value="<?=e($q)?>" placeholder="Event, user, IP or description"><select name="risk"><option value="">All risk levels</option><?php foreach(['LOW','MEDIUM','HIGH','CRITICAL'] as $r):?><option <?=$risk===$r?'selected':''?>><?=$r?></option><?php endforeach?></select><button class="btn">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Risk</th><th>Event</th><th>User</th><th>IP</th><th>Device</th><th>Description</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><span class="risk <?=strtolower(e($r['risk_level']))?>"><?=e($r['risk_level'])?></span></td><td><?=e($r['event_type'])?></td><td><?=e($r['name']??'System/Admin')?></td><td><?=e($r['ip_address']??'—')?></td><td><?=e($r['device_id']??'—')?></td><td><?=e($r['description'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach?></tbody></table><?php if(!$rows):?><div class="empty">No security events match these filters.</div><?php endif?></div><div class="pagination"><?php for($i=1;$i<=ceil($total/$limit);$i++):?><a href="?<?=e(http_build_query(['q'=>$q,'risk'=>$risk,'page'=>$i]))?>"><?=$i?></a><?php endfor?></div></section><?php require APP_ROOT.'/includes/footer.php';
